 $('peel').addEventListener('click',peel);$('sound').addEventListener('click',()=>{s.sound=!s.sound;$('sound').textContent=s.sound?'🔔':'🔕';save();notify(s.sound?'Sound cues on!':'Sound cues muted')});$('reset').addEventListener('click',()=>{if(confirm('Start over with a fresh potato farm? This clears your saved game.')){localStorage.removeItem('spud-save');s={...defaults,last:Date.now(),started:Date.now()};update();notify('Fresh start! Your first spud is ready.')}});
